/// A bookmark saved by the reader.
struct Bookmark: Codable, Equatable {
    let id: UUID
    var title: String
    var url: URL
}

protocol BookmarkStoring {
    func save(_ bookmark: Bookmark) throws
    func all() -> [Bookmark]
}

